  --ap-border:#e2dfd5; --ap-gold:#ddc18c; --ap-radius:18px;
  max-width:1360px!important; width:100%!important; padding:32px 28px 64px!important;
  color:#142238; background:none!important;
}
.ap-workspace::before,.ap-workspace::after { display:none!important; }
.ap-workspace :is(button,input,textarea,select) { font-family:inherit; }
.ap-workspace :is(a,button,input,textarea,select):focus-visible,
.ap-workspace-page :is(.ss-modal button,.ap-detail-dialog button):focus-visible {
  outline:3px solid #947337!important; outline-offset:3px;
}
.ap-workspace [hidden] { display:none!important; }
.ap-workspace .ap-hero {
  min-height:0!important;
  display:grid!important; grid-template-columns:96px minmax(0,1fr) 290px!important;
  gap:24px!important; align-items:center!important; padding:26px!important; margin:0 0 24px!important;
  background:#fff!important; border:1px solid #e2dfd5!important; border-radius:18px!important;
  box-shadow:0 8px 24px rgba(20,34,56,.04)!important; overflow:visible!important;
}
.ap-workspace .ap-hero::before { display:none!important; }
.ap-workspace .ap-hero .ap-hero-logo {
  width:96px!important; height:96px!important; min-width:0!important; aspect-ratio:1;
  margin:0!important; padding:3px!important; border-radius:14px!important; background:#faf9f5!important;
  border:1px solid #e2dfd5!important; box-shadow:none!important; align-self:center!important;
}
.ap-workspace .ap-hero-logo img { width:100%!important; height:100%!important; padding:0!important; object-fit:contain!important; }
