  /* ─── Modal DOM (single, reused) ────────────────────────────────────────── */
  var overlay, modal, heroImg, thumbsEl, detailEl, closeBtn;
  var currentGallery = [], currentIdx = 0;
  var modalOpener = null, previousOverflow = '';

  function buildModal() {
    overlay = document.createElement('div');
    overlay.className = 'ss-overlay';
    overlay.inert = true;
    overlay.setAttribute('aria-hidden', 'true');
    overlay.addEventListener('click', function (e) {
      if (e.target === overlay) closeModal();
    });

    modal = document.createElement('div');
    modal.className = 'ss-modal';
    modal.setAttribute('role', 'dialog');
    modal.setAttribute('aria-modal', 'true');
    modal.setAttribute('aria-labelledby', 'ssBuilderModalTitle');
    modal.addEventListener('click', function (e) { e.stopPropagation(); });

    closeBtn = document.createElement('button');
    closeBtn.className = 'ss-modal__x';
    closeBtn.setAttribute('aria-label', 'Close');
    closeBtn.innerHTML = '&#10005;';
    closeBtn.addEventListener('click', closeModal);

    var imgSide = document.createElement('div');
    imgSide.className = 'ss-modal__img';

    heroImg = document.createElement('img');
    heroImg.className = 'ss-modal__hero';
    heroImg.alt = '';
    heroImg.loading = 'eager';

    thumbsEl = document.createElement('div');
    thumbsEl.className = 'ss-modal__thumbs';

    imgSide.appendChild(heroImg);
    imgSide.appendChild(thumbsEl);

    detailEl = document.createElement('div');
    detailEl.className = 'ss-modal__detail';

    modal.appendChild(closeBtn);
    modal.appendChild(imgSide);
    modal.appendChild(detailEl);
    overlay.appendChild(modal);
    document.body.appendChild(overlay);

    document.addEventListener('keydown', function (e) {
      if (!overlay.classList.contains('open')) return;
      if (e.key === 'Tab') {
        var focusable = Array.from(modal.querySelectorAll('button:not([disabled]),a[href],[tabindex="0"]')).filter(function (node) { return node.getClientRects().length; });
        var first = focusable[0], last = focusable[focusable.length - 1];
        if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
        else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
      }
      if (e.key === 'Escape') closeModal();
      if (e.key === 'ArrowLeft' && overlay.classList.contains('open')) setGalleryIdx(currentIdx - 1);
      if (e.key === 'ArrowRight' && overlay.classList.contains('open')) setGalleryIdx(currentIdx + 1);
    });
  }

  function setGalleryIdx(n) {
    if (!currentGallery.length) return;
    currentIdx = (n + currentGallery.length) % currentGallery.length;
    heroImg.src = currentGallery[currentIdx];
    thumbsEl.querySelectorAll('.ss-modal__thumb').forEach(function (th, i) {
      th.classList.toggle('on', i === currentIdx);
    });
  }

  function populateModal(b) {
    currentGallery = b.gallery;
    currentIdx = 0;
    heroImg.src = currentGallery[0];
    heroImg.alt = b.name;
    modal.setAttribute('aria-label', b.name);

    thumbsEl.innerHTML = '';
    if (currentGallery.length > 1) {
      currentGallery.forEach(function (url, i) {
        var th = document.createElement('button');
        th.type = 'button';
        th.setAttribute('aria-label', 'View product image ' + (i + 1));
        th.className = 'ss-modal__thumb' + (i === 0 ? ' on' : '');
        var tImg = document.createElement('img');
        tImg.src = url;
        tImg.alt = i === 0 ? 'Front' : 'Back';
        tImg.loading = 'lazy';
        th.appendChild(tImg);
        th.addEventListener('click', function () { setGalleryIdx(i); });
        thumbsEl.appendChild(th);
      });
      thumbsEl.style.display = 'flex';
    } else {
      thumbsEl.style.display = 'none';
    }

    var rows = [{ label: b.pricing[0].label, note: b.pricing[0].note, price: fmtPrice(frontPrice(b)) }];
    var bp = backPrice(b);
    if (bp != null && b.pricing[1]) {
      rows.push({ label: b.pricing[1].label, note: b.pricing[1].note, price: fmtPrice(bp) });
    }
    var priceRows = rows.map(function (p) {
      return '<div class="ss-modal__price-row">' +
        '<div><div class="ss-modal__pl">' + esc(p.label) + '</div><div class="ss-modal__pn">' + esc(p.note) + '</div></div>' +
        '<div class="ss-modal__pv">' + esc(p.price) + '</div>' +
        '</div>';
    }).join('');

    var specChips = b.specs.map(function (s) {
      return '<span class="ss-modal__spec">' + esc(s) + '</span>';
    }).join('');

    detailEl.innerHTML =
      '<div class="ss-modal__scroll">' +
        '<span class="ss-modal__chip">' + esc(b.badge) + '</span>' +
        (b.personalize ? '<span class="ss-modal__chip ss-modal__chip--pers">\u2726 Name & Number available</span>' : '') +
        '<div class="ss-modal__title" id="ssBuilderModalTitle">' + esc(b.name) + '</div>' +
        '<p class="ss-modal__desc">' + esc(b.desc) + '</p>' +
        (b.personalize ? '<p class="ss-modal__pers-note">\u2726 <strong>Name &amp; Number:</strong> flip one switch in the builder and every buyer can add their own name and number to the back \u2014 printed just for them, no extra work for you.</p>' : '') +
        '<div class="ss-modal__specs">' + specChips + '</div>' +
        '<div class="ss-modal__div"></div>' +
        '<div class="ss-modal__price-head">Retail pricing</div>' +
        '<div class="ss-modal__price-card">' + priceRows + '</div>' +
        '<div class="ss-modal__meta-head">Available sizes</div>' +
        '<div class="ss-modal__meta-val">' + esc(b.sizes) + '</div>' +
        '<div class="ss-modal__meta-head">Colors</div>' +
        '<div class="ss-modal__meta-val">' + esc(b.colors) + '</div>' +
      '</div>' +
      '<div class="ss-modal__foot">' +
        '<button class="ss-modal__cta" data-builder-id="' + esc(b.id) + '">Customize this product →</button>' +
      '</div>';

    detailEl.querySelector('.ss-modal__cta').addEventListener('click', function () {
      closeModal();
      launch(b);
    });
  }

  function openModal(b) {
    if (!overlay) buildModal();
    modalOpener = document.activeElement;
    previousOverflow = document.body.style.overflow;
    populateModal(b);
    overlay.inert = false;
    overlay.setAttribute('aria-hidden', 'false');
    overlay.classList.add('open');
    document.body.style.overflow = 'hidden';
    closeBtn.focus();
  }

  function closeModal() {
    if (!overlay || !overlay.classList.contains('open')) return;
    overlay.classList.remove('open');
    document.body.style.overflow = previousOverflow;
    if (modalOpener && modalOpener.isConnected) modalOpener.focus();
    overlay.inert = true;
    overlay.setAttribute('aria-hidden', 'true');
  }

  /* ─── Card factory ──────────────────────────────────────────────────────── */
  function makeCard(b) {
    var card = document.createElement('div');
    card.className = 'ss-cat';
    card.setAttribute('data-ss-builder-id', b.id);
    card.setAttribute('data-ss-builder-categories', builderCategories(b).join(' '));
    card.setAttribute('role', 'button');
    card.setAttribute('tabindex', '0');
    card.setAttribute('aria-label', 'Preview ' + b.name);

    var media = document.createElement('div');
    media.className = 'ss-cat__media';

    var img = document.createElement('img');
    img.src = b.gallery[0];
    img.alt = b.name;
    img.loading = 'eager';
    img.decoding = 'async';

    var badge = document.createElement('span');
    badge.className = 'ss-cat__badge';
    badge.textContent = b.badge;

    media.appendChild(img);
    media.appendChild(badge);

    if (b.personalize) {
      var pers = document.createElement('span');
      pers.className = 'ss-cat__pers';
      pers.textContent = '\u2726 Name & Number';
      pers.title = 'Buyers can add their own name and number to the back';
      media.appendChild(pers);
    }

    var info = document.createElement('div');
    info.className = 'ss-cat__info';
    info.innerHTML =
      '<div class="ss-cat__name">' + esc(b.name) + '</div>' +
      '<div class="ss-cat__price">From ' + esc(fmtPrice(frontPrice(b))) + '</div>' +
      '<div class="ss-cat__hint">' + esc(b.hint) + '</div>';

    card.appendChild(media);
    card.appendChild(info);

    function activate() { card.focus(); openModal(b); }
    card.addEventListener('click', activate);
    card.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); activate(); }
    });

    return card;
  }

  function availableCategories() {
    var present = {};
    BUILDERS.forEach(function (builder) {
      builderCategories(builder).forEach(function (category) { present[category] = true; });
    });
    return CATEGORY_ORDER.filter(function (category) {
      return category.id === 'all' || present[category.id];
    });
  }

  function applyCategoryFilter() {
    var container = $('#apCustomBuildersContainer');
    if (!container) return;
    container.querySelectorAll('.ss-cat').forEach(function (card) {
      var categories = (card.getAttribute('data-ss-builder-categories') || '').split(/\s+/);
      card.hidden = activeCategory !== 'all' && categories.indexOf(activeCategory) === -1;
    });
    var nav = $('#apBuilderCategoryNav');
    if (nav) nav.querySelectorAll('.ss-builder-category-tab').forEach(function (button) {
      var selected = button.getAttribute('data-category') === activeCategory;
      button.classList.toggle('is-active', selected);
      button.setAttribute('aria-pressed', selected ? 'true' : 'false');
    });
  }

  function renderCategoryNav() {
    var container = $('#apCustomBuildersContainer');
    if (!container) return;
    var existing = $('#apBuilderCategoryNav');
    if (existing) existing.remove();
    var nav = document.createElement('div');
    nav.id = 'apBuilderCategoryNav';
    nav.className = 'ss-builder-category-nav';
    nav.setAttribute('aria-label', 'Filter product builders');
    availableCategories().forEach(function (category) {
      var button = document.createElement('button');
      button.type = 'button';
      button.className = 'ss-builder-category-tab' + (category.id === activeCategory ? ' is-active' : '');
      button.setAttribute('data-category', category.id);
      button.setAttribute('aria-pressed', category.id === activeCategory ? 'true' : 'false');
      button.textContent = category.label;
      button.addEventListener('click', function () {
        activeCategory = category.id;
        applyCategoryFilter();
      });
      nav.appendChild(button);
    });
    container.parentNode.insertBefore(nav, container);
  }

  /* ─── Styles injection ──────────────────────────────────────────────────── */
  function injectStyles() {
    if ($('#ss-catalog-css')) return;
    var s = document.createElement('style');
    s.id = 'ss-catalog-css';
    s.textContent = CSS;
    document.head.appendChild(s);
  }

  /* ─── Render ────────────────────────────────────────────────────────────── */
  function renderCards(force) {
    var container = $('#apCustomBuildersContainer');
    var section = $('#apCustomBuildersSection');
    var empty = $('#apCustomBuildersEmpty');
    var count = $('#apBuilderProductCount');

    if (!container) return false;
    if (!force && container.getAttribute('data-ss-v') === VERSION && container.children.length === BUILDERS.length) return true;

    injectStyles();
    container.innerHTML = '';
    BUILDERS.forEach(function (b) { container.appendChild(makeCard(b)); });
    renderCategoryNav();
    applyCategoryFilter();
    container.setAttribute('data-ss-v', VERSION);

    if (section) section.style.display = 'block';
    if (empty) empty.style.display = 'none';
    if (count) count.textContent = String(BUILDERS.length);
    return true;
  }

  function shouldRun() {
    return window.location.pathname.indexOf('/pages/admin-powers') !== -1
      || !!$('#apPanelAddProducts')
      || !!$('#apCustomBuildersContainer');
  }

  /* ─── Boot ──────────────────────────────────────────────────────────────── */
  function boot() {
    var tries = 0;
    var pricesRequested = false;
    var catalogRequested = false;
    var timer = setInterval(function () {
      if (shouldRun()) {
        renderCards(false);
        if (!pricesRequested) { pricesRequested = true; fetchLivePrices(); }
        if (!catalogRequested) { catalogRequested = true; fetchDynamicCatalog(); }
      }
      if (++tries >= 240) clearInterval(timer);
    }, 125);

    var obs = new MutationObserver(function () {
      if (!shouldRun()) return;
      var c = $('#apCustomBuildersContainer');
      if (c && (c.getAttribute('data-ss-v') !== VERSION || c.children.length !== BUILDERS.length)) {
        setTimeout(function () { renderCards(true); }, 30);
      }
    });
    obs.observe(document.documentElement, {childList: true, subtree: true});
  }

  ready(boot);
})();

/* Wait for the same Liquid access gate used by the store, not a fixed delay. */
(function () {
  'use strict';
  window.SSWaitForStoreAccess = function (options) {
    var status = options.status;
    var button = options.button;
    var destination = new URL(options.storeUrl, window.location.origin);
    if (destination.origin !== window.location.origin || !/^\/collections\/[^/]+\/?$/.test(destination.pathname)) return;
    destination.search = '';
    destination.hash = '';
    var handle = decodeURIComponent(destination.pathname.split('/')[2]);
    var started = Date.now();
    var finished = false;
    var pending = false;
    button.disabled = true;
    button.textContent = 'Opening your store…';
    status.style.opacity = '1';
    status.style.color = '';
    status.textContent = options.requireAdmin
      ? 'Store claimed! Syncing your admin access with Shopify…'
      : 'You’re added! Syncing your store access with Shopify…';

    function retry() {
      if (finished) return;
      if (Date.now() - started >= 120000) {
        finished = true;
        status.textContent = 'Your access is saved. Shopify is still syncing it—check again in a moment. You do not need to claim again.';
        button.disabled = false;
        button.textContent = 'Check my store access';
        button.onclick = function () { window.SSWaitForStoreAccess(options); };
        return;
      }
      if (Date.now() - started > 20000) status.textContent = 'Your access is saved. Still waiting for Shopify to finish syncing—we’ll open your store automatically.';
      window.setTimeout(check, 2000);
    }

    function check() {
      if (finished || pending) return;
      pending = true;
      var controller = new AbortController();
      var timeout = window.setTimeout(function () { controller.abort(); }, 8000);
      var probe = new URL(destination.toString());
      probe.searchParams.set('ss_access_check', String(Date.now()));
      fetch(probe.toString(), {credentials: 'same-origin', cache: 'no-store', signal: controller.signal})
        .then(function (response) { return response.ok ? response.text() : ''; })
        .then(function (html) {
          if (!html) return;
          var doc = new DOMParser().parseFromString(html, 'text/html');
          var marker = doc.querySelector('[data-ss-store-access][data-ss-store-handle]');
          if (!marker || marker.getAttribute('data-ss-store-handle') !== handle) return;
          var role = marker.getAttribute('data-ss-store-access');
          if (role !== 'admin' && (options.requireAdmin || role !== 'member')) return;
          finished = true;
          status.textContent = 'Access is ready. Opening your store…';
          // No preview parameter or access bypass: Liquid has confirmed membership.
          if (window.__ssStoreAccessNavigate) window.__ssStoreAccessNavigate(destination.pathname);
          else window.location.replace(destination.pathname);
        })
        .catch(function () {})
        .finally(function () {
          window.clearTimeout(timeout);
          pending = false;
          retry();
        });
    }
    check();
  };
})();

