                     Same shape as the Social Engine card below. {% endcomment -%}
                  {%- assign pl_fallback_secret = 'stellasage-god-mode-2026-xK9mP' -%}
                  {%- assign pl_mf_secret = shop.metafields.custom.editor_secret.value | default: shop.metafields.custom.editor_secret -%}
                  {%- assign pl_base = 'https://printfulautomation-production.up.railway.app' -%}
