  .ss-pager { display: flex; justify-content: center; margin: 14px 0 2px; }
  /* [hidden] is a UA rule, and ANY author rule setting display beats it —
     specificity does not enter into it. Without this the pager stays on screen
     until the script's first render, so the very first click lands on a button
     that has no handler yet and appears to do nothing. Which is exactly what it
     did. The same applies to anything else here toggled via .hidden. */
  .ss-pager[hidden],
  .ss-store-search[hidden],
  .ss-store-search-count[hidden],
  .ss-search-empty[hidden] { display: none !important; }
  .ss-pager-btn {
