    display: flex; align-items: center; justify-content: center;
    overflow: hidden; border: 1px solid rgba(15,23,42,0.08); flex-shrink: 0;
  }
  /* One inset for every breakpoint.
     Six different pixel paddings were competing here — 4, 6, 3, 1 and two
     zeroes — and on desktop the zeroes won, so the artwork ran edge to edge
     and the wordmark ended up flush against the rounded corner. A percentage
     is relative to the image's own width, which is the frame's width, so a
     single value stays proportional at 66px and at 104px instead of needing a
     new number each time the frame is resized.
     box-sizing is explicit: without it the padding is added OUTSIDE the 100%
     box and pushes the image out of the frame rather than insetting it. */
  .ss-logo-frame img {
    width: 100%; height: 100%;
    box-sizing: border-box !important;
    object-fit: contain;
    object-position: center center;
    padding: 9% !important;
