    .ss-col-controls {
      width: 100%;
      display: flex;
      flex-direction: row;
      flex-wrap: wrap;
      align-items: center;
      gap: 10px;
      padding: 12px 0 0;
      border-top: 1px solid rgba(15,23,42,0.07);
