{%- comment -%}
  With JavaScript off the pager can never run, so the cards it hid on the
  server would be unreachable rather than merely collapsed. Reveal them all
  and drop the controls: a search box that cannot filter and a button that
  cannot expand are worse than no controls at all.
{%- endcomment -%}
<noscript>
  <style>
    .ss-card-paged-out { display: flex !important; }
    .ss-store-search, .ss-pager { display: none !important; }
  </style>
</noscript>

<script>
(function () {
  'use strict';

  // Ten at a time. A dashboard with sixty stores was laying out and painting
  // all sixty before showing anything, and every card carries a logo, a status
  // block and its own controls — the cost is in the cards, not the data, so
  // showing fewer is the whole fix. Nothing is fetched: every card is already
  // in the page, so "show more" is a class change and is instant.
  var PAGE_SIZE = 10;

  function init() {
    var grid = document.querySelector('.ss-store-grid');
    if (!grid) return;

    var cards = Array.prototype.slice.call(grid.querySelectorAll('.ss-paged-card'));
    if (!cards.length) return;

    var pager = document.querySelector('[data-ss-pager]');
    var button = document.querySelector('[data-ss-show-more]');
    var input = document.querySelector('[data-ss-search]');
    var countEl = document.querySelector('[data-ss-search-count]');

    var shown = PAGE_SIZE;
    var query = '';

    // Read once. Searching re-reads nothing, so typing stays cheap no matter
    // how many stores there are.
    var haystacks = cards.map(function (card) {
      var name = card.getAttribute('data-ss-name') || '';
      var handle = card.getAttribute('data-ss-handle') || '';
      return (name + ' ' + handle).toLowerCase();
    });

    var emptyNote = document.createElement('div');
    emptyNote.className = 'ss-search-empty';
    emptyNote.hidden = true;
    emptyNote.setAttribute('role', 'status');
    grid.parentNode.insertBefore(emptyNote, grid.nextSibling);

    function render() {
      var searching = query.length > 0;
      var matched = 0;

      for (var i = 0; i < cards.length; i++) {
        var card = cards[i];
        var isMatch = !searching || haystacks[i].indexOf(query) !== -1;

        if (!isMatch) {
          card.classList.add('ss-card-filtered');
          continue;
        }

        card.classList.remove('ss-card-filtered');

        // A search reaches the whole account, not just the pages already
        // revealed — otherwise the one store you are looking for is the one
        // the pager is still hiding.
        var visible = searching || matched < shown;
        card.classList.toggle('ss-card-paged-out', !visible);
        matched++;
      }

      if (searching) {
        emptyNote.hidden = matched !== 0;
        if (matched === 0) emptyNote.textContent = 'No stores match "' + query + '".';
      } else {
        emptyNote.hidden = true;
      }

      if (countEl) {
        countEl.hidden = !searching;
        if (searching) {
          countEl.textContent = matched + ' of ' + cards.length;
        }
      }

      if (pager) {
        var remaining = searching ? 0 : cards.length - shown;
        pager.hidden = remaining <= 0;
        if (button && remaining > 0) {
          var next = Math.min(PAGE_SIZE, remaining);
          button.textContent = 'Show ' + next + ' more store' + (next === 1 ? '' : 's');
        }
      }
      document.dispatchEvent(new Event('ss:dashboard-visible'));
    }

    if (button) {
      button.addEventListener('click', function () {
        var firstNew = shown;
        shown += PAGE_SIZE;
        render();
        // Send focus to the first card that just appeared, so the button does
        // not leave a keyboard or screen-reader user stranded where it used
        // to be. Falls back to the button while any remain.
        var target = cards[firstNew];
        if (target && !target.classList.contains('ss-card-paged-out')) {
          target.setAttribute('tabindex', '0');
          target.focus({ preventScroll: true });
        }
      });
    }

    if (input) {
      var debounce;
      input.addEventListener('input', function () {
        clearTimeout(debounce);
        debounce = setTimeout(function () {
          query = input.value.trim().toLowerCase();
          render();
        }, 90);
      });
      // Escape clears, the way a search field is expected to.
      input.addEventListener('keydown', function (event) {
        if (event.key === 'Escape' && input.value !== '') {
          event.preventDefault();
          input.value = '';
          query = '';
          render();
        }
      });
    }

    render();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
</script>


