            {%- endcomment -%}
            {%- capture return_path -%}
              {{ request.path }}?shop={{ shop_handle }}{% if code != blank %}&code={{ code }}{% endif %}
            {%- endcapture -%}
            <a class="sf-btn sf-btn--shop"
               href="{{ routes.storefront_login_url }}?return_to={{ return_path | strip | url_encode }}">
              <span class="sf-btn__title">{% if is_claimable %}Sign in to claim store{% else %}Sign in or create account{% endif %}</span>
              <span class="sf-btn__meta">{% if is_claimable %}First verified claimant becomes admin{% else %}Continue with Shop or email{% endif %}</span>
            </a>
            <a class="sf-btn sf-btn--outline sf-btn--preview" href="{{ preview_url }}">Preview the store</a>
          </div>

          <p class="sf-note">No password needed <span aria-hidden="true">&bull;</span> Securely handled by Shopify</p>

          <details class="sf-about">
            <summary>Tell me more about Stella &amp; Sage</summary>
            <div class="sf-about__body">
              <p>Stella &amp; Sage is a veteran-owned small business that builds always-open private team stores. Every item is made to order and ships directly to each buyer&mdash;no group minimums, inventory, or ordering deadline.</p>
              <a href="/" class="sf-about__link">Visit Stella &amp; Sage &rarr;</a>
            </div>
          </details>
        </div>
      </div>
    {%- endif -%}

  {%- elsif store_entry == nil and shop_handle != blank -%}
    <div class="sf-card sf-card--error">
      <h2>Store Not Found</h2>
      <p>The link you used seems to be invalid or the store "<strong>{{ shop_handle }}</strong>" does not exist.</p>
      <a href="/pages/portal" class="sf-btn sf-btn--outline">Back to Dashboard</a>
    </div>

  {%- elsif shop_handle == blank -%}
    <div class="sf-card sf-card--error">
      <h2>Invalid Link</h2>
      <p>This link is missing the shop ID. Please check the URL.</p>
      <a href="/pages/portal" class="sf-btn sf-btn--outline">Back to Dashboard</a>
    </div>

  {%- else -%}
    {%- comment -%} SUCCESS VIEW: SHOW PREVIEW CARD {%- endcomment -%}
    <div class="sf-card">
      <div class="sf-logo-area">
        {%- if store_logo != blank -%}
          {{ store_logo | image_url: width: 300 | image_tag: class: 'sf-store-logo', loading: 'eager' }}
        {%- else -%}
          <div class="sf-logo-fallback">{{ store_name | slice: 0, 2 | upcase }}</div>
        {%- endif -%}
      </div>

      <div class="sf-content">
        <span class="sf-badge">{% if is_claimable %}Store ready to claim{% else %}You have been invited to join{% endif %}</span>
        <h1 class="sf-title">{{ store_name }}</h1>
        <p class="sf-sub">{% if is_claimable %}Claim this live store to become its first administrator.{% else %}Click below to add this private collection to your dashboard.{% endif %}</p>

        <button id="btnJoin" class="sf-btn sf-btn--primary" onclick="joinStore()">
          {% if is_claimable %}Claim Store &amp; Become Admin{% else %}Join Storefront{% endif %}
        </button>

        <div id="joinStatus" class="sf-status"></div>
      </div>
    </div>

    <script src="{{ 'ss-store-access-ready.js' | asset_url }}" defer></script>
    <script>
      function joinStore() {
        var btn = document.getElementById('btnJoin');
        var statusEl = document.getElementById('joinStatus');

        // 1. Lock the Button immediately
        btn.disabled = true;
        btn.innerHTML = '<span class="sf-spinner-small"></span> Processing...';
        statusEl.innerHTML = "Initializing secure connection...";
        statusEl.classList.add('active');

        // Route the join through our OWN backend: the Printful_Automation App
        // Proxy relay forwards to studio-uploader. The App Proxy signs the
        // request and injects the VERIFIED logged-in customer id server-side,
        // so we deliberately send no id here. Claimable stores atomically grant
        // ADMIN + MEMBER to the first claimant; normal stores grant MEMBER only.
        var joinUrl = "/apps/ss/relay/storefront/{{ shop_handle }}/join";

        var didError = false;
        var claimedAdmin = false;
        var accessPending = false;

        // 2. Save access, then wait for the real storefront gate to observe it.
        fetch(joinUrl, {
          method: 'POST',
          headers: {'Content-Type':'application/json'},
          body: '{}'
        })
        .then(function(res){
          return res.json().catch(function(){ return {}; }).then(function(data){
            if(!res.ok || !data.ok){
              throw new Error(((data && data.error) || 'Join failed') + ' [HTTP ' + res.status + ']');
            }
            claimedAdmin = data.claimed_admin === true;
            accessPending = true;
            window.SSWaitForStoreAccess({
              storeUrl: {{ collection_url | json }},
              requireAdmin: claimedAdmin,
              button: btn,
              status: statusEl
            });
          });
        })
        .catch(function(err){
          console.error(err);
          didError = true;
          btn.disabled = false;
          btn.innerHTML = 'Try Again';
          statusEl.innerHTML = (err && err.message) ? err.message : 'Connection Error. Please try again.';
          statusEl.style.color = 'red';
        });

        // 3. Progress steps — visual feedback during the backend call + propagation wait.
        // Success message and redirect are driven by the .then() block above.
        var steps = [
          { time: 1500, text: "Verifying invite..." },
          { time: 4000, text: "Granting access permissions..." },
          { time: 7000, text: "Syncing your dashboard..." },
          { time: 10500, text: "Almost ready…" }
        ];

        steps.forEach(function(step) {
          setTimeout(function() {
            if (didError || accessPending) return;
            statusEl.style.opacity = '0';
            setTimeout(function(){
              if (didError || accessPending) return;
              statusEl.innerHTML = step.text;
              statusEl.style.opacity = '1';
            }, 300);
          }, step.time);
        });
      }
    </script>
  {%- endif -%}

