  .ap-nuke-dialog__title {
    font-weight: 900; font-size: 20px; color: #dc2626;
    margin: 0 0 8px; letter-spacing: -0.02em;
  }
  .ap-nuke-dialog__warning {
    font-size: 14px; line-height: 1.55; color: #374151; margin: 0 0 16px;
  }
  .ap-nuke-confirm-input {
    width: 100%; padding: 11px 14px; margin-bottom: 16px;
    border: 1.5px solid rgba(239,68,68,0.4); border-radius: 10px;
    font-size: 14px; font-family: var(--ap-font); color: #0f172a;
    background: #fff; box-sizing: border-box;
  }
  .ap-nuke-confirm-input:focus { outline: none; border-color: #ef4444; box-shadow: 0 0 0 3px rgba(239,68,68,0.15); }
  .ap-nuke-actions { display: flex; gap: 10px; flex-wrap: wrap; }
  .ap-nuke-actions .ap-btn { flex: 1; min-width: 120px; }
  .ap-nuke-log {
    margin-top: 16px; padding: 14px;
    background: #0f172a; color: #94a3b8;
    border-radius: 10px; font-size: 11px;
    font-family: monospace; white-space: pre-wrap;
    max-height: 180px; overflow-y: auto; display: none;
    line-height: 1.6;
  }

  /* ── REBUILD MODAL ─────────────────────────────────────── */
  .ap-rebuild-overlay {
    display: none; position: fixed; inset: 0;
    background: rgba(15,23,42,0.75); z-index: 10000;
    align-items: center; justify-content: center; padding: 24px;
    backdrop-filter: blur(6px);
  }
  .ap-rebuild-overlay.open { display: flex; }
  .ap-rebuild-dialog {
    width: min(480px, 100%); background: #fff;
    border-radius: 20px; padding: 40px 36px;
    box-shadow: 0 32px 80px rgba(0,0,0,0.32);
    text-align: center;
    animation: ap-fadeIn 0.3s ease-out;
  }
  .ap-rebuild-icon { font-size: 48px; margin-bottom: 16px; }
  .ap-rebuild-title {
    font-size: 22px; font-weight: 900; color: #0f172a;
    margin: 0 0 16px; letter-spacing: -0.02em;
  }
  .ap-rebuild-body {
    font-size: 15px; line-height: 1.6; color: #374151;
    margin: 0 0 20px;
  }
  .ap-rebuild-sub {
    font-size: 13px; color: #64748b; margin: 0 0 24px;
  }
  .ap-rebuild-bar {
    height: 6px; background: #e2e8f0; border-radius: 3px; overflow: hidden;
  }
  .ap-rebuild-bar-fill {
    height: 100%; width: 0%; background: linear-gradient(90deg, #6366f1, #10b981);
    border-radius: 3px;
    animation: ap-rebuild-drain 5s linear forwards;
  }
  @keyframes ap-rebuild-drain {
    from { width: 0%; }
    to   { width: 100%; }
  }
  @media(max-width:480px) {
    .ap-rebuild-dialog { padding: 28px 20px; }
    .ap-rebuild-title { font-size: 18px; }
  }

  /* ── MAIN TABS ─────────────────────────────────────────── */
  .ap-main-card {
    background: var(--ap-card); border: 1px solid var(--ap-border);
    border-radius: var(--ap-radius); box-shadow: var(--ap-shadow);
    overflow: hidden;
  }
  .ap-main-tabs {
    display: flex; gap: 0; border-bottom: 2px solid var(--ap-border);
    background: #f8fafc; overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: none;
  }
  .ap-main-tabs::-webkit-scrollbar { display: none; }
  .ap-main-tab-btn {
    flex: 1; min-width: 0; padding: 14px 10px;
    font-family: var(--ap-font); font-size: 13px; font-weight: 700;
    color: var(--ap-gray); background: none; border: none;
    border-bottom: 3px solid transparent; cursor: pointer;
    transition: all 0.15s; white-space: nowrap; text-align: center;
    margin-bottom: -2px; overflow: hidden; text-overflow: ellipsis;
  }
  .ap-main-tab-btn:hover { color: var(--ap-text); background: #f1f5f9; }
  .ap-main-tab-btn.active {
    color: #fff; background: var(--ap-accent);
    border-bottom-color: var(--ap-accent2);
  }
  .ap-main-panel { display: none; padding: 28px; }
  .ap-main-panel.active { display: block; }
  .ap-main-tabs-wrap { position: relative; }
  .ap-tab-icon { display: block; font-size: 16px; line-height: 1; }
  .ap-tab-label { display: block; font-size: 10px; font-weight: 700; margin-top: 2px; }
  @media(max-width:600px) {
    /* Outer wrap */
    .ap-wrap { padding: 16px 14px 60px; }
    /* Hero */
    .ap-hero { padding: 22px 18px; margin-bottom: 18px; }
    .ap-hero h1 { font-size: 22px; }
    .ap-hero-actions { width: 100%; flex-direction: column; }
    .ap-hero-actions .ap-btn { width: 100%; justify-content: center; }
    /* Tabs — all 5 fit on screen, no scroll */
    .ap-main-tabs { overflow-x: hidden; -webkit-overflow-scrolling: auto; }
    .ap-main-tab-btn { flex: 1 1 0; min-width: 0; padding: 10px 4px; font-size: 11px; white-space: normal; line-height: 1.2; overflow: visible; text-overflow: clip; }
    /* Remove the scroll-hint fade gradient */
    .ap-main-tabs-wrap::after { display: none; }
    .ap-tab-icon { font-size: 18px; }
    .ap-tab-label { font-size: 9px; }
    /* Panel content */
    .ap-main-panel { padding: 16px; }
    .ap-danger-zone-body { padding: 4px 0 0; }
    /* Danger rows — stack vertically */
    .ap-danger-row { flex-direction: column; gap: 10px; }
    .ap-danger-row .ap-btn { width: 100%; justify-content: center; }
    /* Forms */
    .ap-radio { padding: 12px; }
    .ap-form-group { margin-bottom: 14px; }
    .ap-input, .ap-textarea, .ap-select { font-size: 16px; }
    /* Member rows */
    .ap-member-row { flex-wrap: wrap; gap: 8px; }
    .ap-member-row .ap-btn { font-size: 12px; padding: 7px 12px; }
    /* Product row action buttons */
    .ap-product-row__actions { flex-wrap: wrap; gap: 6px; }
  }
  @media(max-width:480px) {
    /* Auth card on tiny phones */
    .ap-auth-card { padding: 28px 18px; }
    .ap-auth-wrap { margin: 32px auto; }
  }

  /* ── DANGER ROW ──────────────────────────────────────────── */
  .ap-danger-zone-body { padding: 4px 28px 24px; }
  .ap-danger-row {
    display: flex; align-items: flex-start; justify-content: space-between;
    gap: 20px; padding: 18px 0;
  }
  .ap-danger-row + .ap-danger-row { border-top: 1px solid rgba(239,68,68,0.2); }
  .ap-danger-row-left { display: flex; align-items: flex-start; gap: 14px; flex: 1; min-width: 0; }
  .ap-danger-row-icon { font-size: 22px; flex-shrink: 0; line-height: 1.2; }
  .ap-danger-row-title { font-size: 14px; font-weight: 800; color: var(--ap-text); margin-bottom: 4px; }
  .ap-danger-row-desc { font-size: 12px; color: var(--ap-gray); line-height: 1.5; }
  .ap-btn--sm {
    padding: 8px 16px; font-size: 13px; flex-shrink: 0;
    align-self: center; white-space: nowrap;
  }

  /* ── PRODUCT THUMB ───────────────────────────────────────── */
  .ap-product-thumb {
    width: 52px; height: 52px; border-radius: 8px; object-fit: cover;
    background: #f1f5f9; flex-shrink: 0; display: block;
  }
  .ap-product-thumb-empty {
    width: 52px; height: 52px; border-radius: 8px;
    background: #f1f5f9; flex-shrink: 0;
  }
  .ap-btn--outline-sm {
    background: transparent; border: 1px solid var(--ap-border); color: var(--ap-text);
    padding: 6px 12px; font-size: 12px; font-weight: 700; border-radius: 8px;
    cursor: pointer; transition: all 0.15s; font-family: var(--ap-font);
  }
  .ap-btn--outline-sm:hover { background: #f8fafc; border-color: #94a3b8; }
  .ap-btn--danger-sm {
    background: #fee2e2; color: #991b1b;
    padding: 6px 12px; font-size: 12px; font-weight: 700; border-radius: 8px;
    cursor: pointer; transition: all 0.15s; border: none; font-family: var(--ap-font);
  }
  .ap-btn--danger-sm:hover { background: #fecaca; }
  .ap-edit-placement-btn {
    display: inline-flex; align-items: center; gap: 6px;
    padding: 6px 12px; background: #3b82f6; color: #ffffff;
    border-radius: 8px; font-size: 12px; font-weight: 700;
    text-decoration: none; border: none; cursor: pointer;
    transition: background 0.15s ease; font-family: var(--ap-font);
    white-space: nowrap; flex-shrink: 0;
  }
  .ap-edit-placement-btn:hover { background: #2563eb; color: #ffffff; text-decoration: none; }
  .ap-edit-placement-btn--disabled {
    background: #94a3b8; cursor: not-allowed; pointer-events: auto;
  }
  .ap-edit-placement-btn--disabled:hover { background: #94a3b8; }
  .ap-product-row__actions {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    justify-content: flex-start;
    flex-shrink: 0;
  }
  .ap-rebuilding-inline {
    display: flex;
    flex-direction: column;
    gap: 6px;
    min-width: 200px;
    flex: 1;
    max-width: 320px;
  }
  .ap-rebuilding-inline__bar {
    height: 6px;
    background: #dbeafe;
    border-radius: 3px;
    overflow: hidden;
    position: relative;
  }
  .ap-rebuilding-inline__bar-fill {
    position: absolute;
    top: 0; left: -30%;
    width: 30%; height: 100%;
    background: linear-gradient(90deg, transparent, #3b82f6, transparent);
    animation: ap-rebuilding-inline-sweep 1.4s ease-in-out infinite;
  }
  @keyframes ap-rebuilding-inline-sweep {
    0%   { left: -30%; }
    100% { left: 100%; }
  }
  .ap-rebuilding-inline__label {
    font-size: 12px;
    color: #1e40af;
    font-weight: 600;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  .ap-rebuilding-inline__step { color: #64748b; font-weight: 500; }
  .ap-rebuilding-inline.ap-rebuilding-inline--success .ap-rebuilding-inline__bar-fill {
    left: 0; width: 100%; animation: none; background: #10b981;
  }
  .ap-rebuilding-inline.ap-rebuilding-inline--success .ap-rebuilding-inline__label {
    color: #065f46;
  }
  .ap-rebuilding-inline.ap-rebuilding-inline--error .ap-rebuilding-inline__bar-fill {
    left: 0; width: 100%; animation: none; background: #ef4444;
  }
  .ap-rebuilding-inline.ap-rebuilding-inline--error .ap-rebuilding-inline__label {
    color: #991b1b;
  }
  @media (max-width: 600px) {
    .ap-rebuilding-inline { min-width: 100%; max-width: 100%; }
  }
  .ap-rebuilding-toast {
    position: fixed;
    bottom: 20px;
    left: 50%;
    transform: translateX(-50%);
    max-width: min(540px, calc(100vw - 32px));
    padding: 16px 44px 16px 20px;
    background: #0f172a;
    color: #ffffff;
    border-radius: 12px;
    box-shadow: 0 12px 32px rgba(0,0,0,0.35);
    font-family: var(--ap-font);
    font-size: 14px;
    line-height: 1.45;
    z-index: 9999;
    animation: ap-rebuilding-toast-in 0.25s ease-out;
  }
  .ap-rebuilding-toast strong { color: #86efac; font-weight: 700; }
  .ap-rebuilding-toast__close {
    position: absolute;
    top: 8px;
    right: 8px;
    width: 28px;
    height: 28px;
    border: none;
    background: transparent;
    color: #cbd5e1;
    font-size: 16px;
    cursor: pointer;
    border-radius: 6px;
  }
  .ap-rebuilding-toast__close:hover { background: rgba(255,255,255,0.08); color: #ffffff; }
  @keyframes ap-rebuilding-toast-in {
    from { opacity: 0; transform: translate(-50%, 12px); }
    to   { opacity: 1; transform: translate(-50%, 0); }
  }
  .ap-editor-overlay {
    display: none;
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.65);
    z-index: 9998;
    align-items: stretch;
    justify-content: center;
    padding: 24px;
    backdrop-filter: blur(4px);
  }
  .ap-editor-overlay.open { display: flex; }
  .ap-editor-dialog {
    width: min(1080px, 100%);
    max-height: calc(100vh - 48px);
    background: #1a1a1a;
    border-radius: 16px;
    box-shadow: 0 32px 80px rgba(0,0,0,0.55);
    display: flex;
    flex-direction: column;
    overflow: hidden;
    animation: ap-editor-fadein 0.2s ease-out;
  }
  @keyframes ap-editor-fadein {
    from { opacity: 0; transform: translateY(10px); }
    to   { opacity: 1; transform: translateY(0); }
  }
  .ap-editor-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    background: #0f172a;
    color: #fff;
    font-family: var(--ap-font);
    font-weight: 700;
    font-size: 14px;
    border-bottom: 1px solid #2a2a2a;
    flex-shrink: 0;
  }
  .ap-editor-close {
    background: rgba(255,255,255,0.08);
    border: 1px solid rgba(255,255,255,0.15);
    color: #fff;
    width: 32px;
    height: 32px;
    border-radius: 8px;
    font-size: 14px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: background 0.15s;
  }
  .ap-editor-close:hover { background: rgba(255,255,255,0.18); }
  .ap-editor-iframe {
    flex: 1;
    width: 100%;
    border: 0;
    display: block;
    background: #faf9f5;
    min-height: 640px;
  }
  @media (max-width: 900px) {
    .ap-editor-overlay { padding: 0; }
    .ap-editor-dialog {
      width: 100%;
      max-height: 100vh;
      border-radius: 0;
    }
  }
  body.ap-editor-open { overflow: hidden; }

  /* ── SETTINGS LOGO PREVIEW ─────────────────────────────── */
  .ap-settings-logo-new {
    max-width: 120px; max-height: 80px; border-radius: 8px;
    border: 2px solid var(--ap-success); padding: 4px; background: #fff;
    display: block; object-fit: contain; margin-bottom: 8px;
  }


  /* ── V13 DESKTOP ADMIN UPGRADES ───────────────────────── */
  .ap-share-overlay {
    display: none; position: fixed; inset: 0; z-index: 9997;
    background: rgba(15,23,42,0.58); backdrop-filter: blur(5px);
    align-items: center; justify-content: center; padding: 20px;
  }
  .ap-share-overlay.open { display: flex; }
  .ap-share-dialog {
    width: min(520px, 100%); background: #fff; border-radius: 20px;
    border: 1px solid rgba(15,23,42,0.08); box-shadow: 0 32px 80px rgba(0,0,0,0.28);
    padding: 24px; position: relative; animation: ap-fadeIn 0.2s ease-out;
  }
  .ap-share-close {
    position: absolute; top: 14px; right: 14px; width: 34px; height: 34px;
    border-radius: 10px; border: 1px solid var(--ap-border); background: #fff;
    color: var(--ap-text); cursor: pointer; font-weight: 900;
  }
  .ap-share-close:hover { background: #f8fafc; }
  .ap-share-head { padding-right: 44px; margin-bottom: 18px; }
  .ap-share-head h3 { margin: 0 0 5px; font-size: 20px; font-weight: 900; letter-spacing: -0.02em; }
  .ap-share-head p { margin: 0; font-size: 13px; color: var(--ap-gray); line-height: 1.45; }
  .ap-share-dialog .ap-tabs { background: #f8fafc; border: 1px solid var(--ap-border); border-radius: 12px; padding: 4px; }
  .ap-share-dialog .ap-tab-btn { flex: 1; padding: 10px 12px; }
  .ap-share-dialog .ap-tab-btn.active { background: #fff; box-shadow: var(--ap-shadow-sm); }

  .ap-products-grid {
    display: grid; grid-template-columns: minmax(0, 1fr) minmax(360px, 0.82fr);
    gap: 20px; align-items: start;
  }
  .ap-product-box {
    background: #ffffff; border: 1px solid var(--ap-border); border-radius: 18px;
    box-shadow: var(--ap-shadow-sm); padding: 18px; min-width: 0;
  }
  .ap-product-box--custom { background: linear-gradient(180deg, #ffffff 0%, #f8f7ff 100%); }
  .ap-product-box-head {
    display: flex; align-items: center; justify-content: space-between; gap: 12px;
    padding-bottom: 14px; margin-bottom: 14px; border-bottom: 1px solid var(--ap-border);
  }
  .ap-product-box-title { margin: 0; font-size: 16px; font-weight: 900; letter-spacing: -0.01em; color: var(--ap-text); }
  .ap-product-box-sub { margin: 3px 0 0; font-size: 12px; color: var(--ap-gray); line-height: 1.35; }
  .ap-product-count {
    display: inline-flex; align-items: center; justify-content: center; min-width: 28px; height: 28px;
    padding: 0 8px; border-radius: 99px; background: #eef2ff; color: #3730a3;
    font-size: 12px; font-weight: 900;
  }
  .ap-product-section-empty {
    display: none; padding: 28px 14px; text-align: center; color: var(--ap-gray);
    font-size: 13px; border: 1px dashed var(--ap-border); border-radius: 14px; background: #f8fafc;
  }
  .ap-custom-builders-section {
    margin-top: 18px;
    padding-top: 16px;
    border-top: 1px solid var(--ap-border);
  }
  .ap-custom-builders-head {
    margin-bottom: 10px;
  }
  .ap-custom-builders-title {
    margin: 0;
    font-size: 14px;
    font-weight: 900;
    color: var(--ap-text);
    letter-spacing: -0.01em;
  }
  .ap-custom-builders-sub {
    margin: 3px 0 0;
    font-size: 12px;
    color: var(--ap-gray);
    line-height: 1.35;
  }
  .ap-product-editor-wrap { position: relative; display: inline-flex; }
  .ap-product-editor-tip {
    display: none; position: absolute; left: 50%; bottom: calc(100% + 10px); transform: translateX(-50%);
    width: 230px; padding: 10px 12px; background: #0f172a; color: #fff; border-radius: 10px;
    font-size: 12px; line-height: 1.35; font-weight: 600; text-align: center; z-index: 50;
    box-shadow: 0 12px 24px rgba(15,23,42,0.25); pointer-events: none;
  }
  .ap-product-editor-tip::after {
    content: ''; position: absolute; top: 100%; left: 50%; transform: translateX(-50%);
    border: 6px solid transparent; border-top-color: #0f172a;
  }
  .ap-product-editor-wrap:hover .ap-product-editor-tip { display: block; }

  @media (max-width: 980px) {
    .ap-products-grid { grid-template-columns: 1fr; }
  }
  @media (max-width: 600px) {
    .ap-wrap { max-width: 100%; padding: 16px 14px 60px; }
    .ap-products-grid { gap: 14px; }
    .ap-product-box { padding: 14px; }
    .ap-product-box-head { align-items: flex-start; }
    .ap-share-dialog { padding: 20px 16px; }
    .ap-copy-row { flex-direction: column; }
  }



  /* ─────────────────────────────────────────────────────────────
     V14 — STELLA & SAGE PREMIUM ADMIN CONTROL CENTER
     Theme-only upgrade. Existing IDs, buttons, modals, and API hooks remain intact.
  ───────────────────────────────────────────────────────────── */
  :root {
    --ap-bg: #fbf8f1;
    --ap-card: rgba(255,255,255,0.82);
    --ap-text: #11100e;
    --ap-gray: rgba(17,16,14,0.58);
    --ap-muted: rgba(17,16,14,0.44);
    --ap-border: rgba(17,16,14,0.085);
    --ap-border-strong: rgba(17,16,14,0.13);
    --ap-accent: #11100e;
    --ap-accent2: #a9955d;
    --ap-gold: #a9955d;
    --ap-gold-soft: rgba(183,163,106,0.12);
    --ap-success: #10b981;
    --ap-danger: #ef4444;
    --ap-shadow-sm: 0 10px 28px rgba(17,16,14,0.055);
    --ap-shadow: 0 24px 80px rgba(17,16,14,0.075);
    --ap-shadow-lg: 0 42px 140px rgba(17,16,14,0.16);
    --ap-radius: 30px;
    --ap-font: -apple-system, BlinkMacSystemFont, "SF Pro Display", "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  }

  .ap-wrap {
    width: min(1760px, calc(100vw - 32px));
    max-width: none;
    margin: 0 auto;
    padding: 38px 0 96px;
    font-family: var(--ap-font);
    color: var(--ap-text);
  }

  .ap-wrap::before {
    content: "";
    position: fixed;
    inset: 0;
    z-index: -1;
    pointer-events: none;
    background:
      radial-gradient(circle at 18% 5%, rgba(183,163,106,0.10), transparent 31%),
      radial-gradient(circle at 86% 8%, rgba(255,255,255,0.92), transparent 26%),
      linear-gradient(180deg, #fbf8f1 0%, #fffdf9 24%, #ffffff 54%, #fbfaf7 100%);
  }

  .ap-auth-card,
  .ap-main-card,
  .ap-card,
  .ap-danger-card,
  .ap-share-dialog,
  .ap-nuke-dialog,
  .ap-rebuild-dialog {
    border-radius: var(--ap-radius);
    border: 1px solid rgba(255,255,255,0.78);
    background: linear-gradient(145deg, rgba(255,255,255,0.90), rgba(255,255,255,0.64));
    box-shadow: var(--ap-shadow);
    backdrop-filter: blur(22px);
    -webkit-backdrop-filter: blur(22px);
  }

  .ap-hero {
    min-height: 286px;
    padding: clamp(28px, 4vw, 54px);
    margin-bottom: 22px;
    border-radius: 44px;
    align-items: stretch;
    overflow: hidden;
    background:
      radial-gradient(circle at 12% 0%, rgba(183,163,106,0.22), transparent 38%),
      radial-gradient(circle at 92% 10%, rgba(255,255,255,0.10), transparent 28%),
      linear-gradient(135deg, #191814 0%, #080807 58%, #1d1709 100%);
    border: 1px solid rgba(183,163,106,0.18);
    box-shadow: 0 46px 160px rgba(17,16,14,0.24);
  }

  .ap-hero::before {
    background:
      linear-gradient(90deg, rgba(255,255,255,0.08), transparent 44%),
      radial-gradient(circle at 78% 24%, rgba(183,163,106,0.16), transparent 44%);
  }

  .ap-hero-left,
  .ap-hero-actions {
    position: relative;
    z-index: 1;
  }

  .ap-hero-title-row {
    display: flex;
    align-items: center;
    gap: 22px;
  }

  .ap-hero-logo {
    width: 104px;
    height: 104px;
    border-radius: 32px;
    display: grid;
    place-items: center;
