  .ap-frw-helper { font-size: 12px; color: rgba(17,16,14,.50); margin: 6px 0 0; line-height: 1.45; }


/* ═══════════════════════════════════════════════════════════════
   REDESIGN v3 — Hero (logo left · info center · buttons far right)
   ═══════════════════════════════════════════════════════════════ */

  .ap-hero {
    display: flex !important;
    flex-direction: row !important;
    flex-wrap: nowrap !important;
    align-items: center !important;
    gap: clamp(20px, 2.6vw, 40px) !important;
    min-height: 0 !important;
    padding: clamp(22px, 2.6vw, 38px) !important;
    margin-bottom: 18px !important;
    overflow: hidden;
  }

  /* Big store image on the left */
  .ap-hero-logo {
    width: clamp(150px, 16vw, 230px) !important;
    height: clamp(150px, 16vw, 230px) !important;
    border-radius: 28px !important;
    flex: 0 0 auto !important;
    align-self: center !important;
    background: rgba(255,255,255,0.96) !important;
    box-shadow: 0 24px 70px rgba(0,0,0,0.28) !important;
  }
  .ap-hero-logo img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    padding: 0 !important;
    border-radius: 28px !important;
