  .ap-hero-logo span {
    font-size: clamp(48px, 6vw, 84px) !important;
    font-weight: 950;
    color: #11100e;
    letter-spacing: -0.06em;
  }

  /* Center info column */
  .ap-hero-info {
    flex: 1 1 auto !important;
    min-width: 0 !important;
    display: flex !important;
    flex-direction: column !important;
    justify-content: center !important;
    gap: 14px !important;
    position: relative;
    z-index: 1;
  }
  .ap-hero-info h1 {
    margin: 0 !important;
    color: #fff;
    font-size: clamp(38px, 4.6vw, 76px) !important;
    line-height: 0.92 !important;
    letter-spacing: -0.05em !important;
    font-weight: 950;
    word-break: break-word;
  }
  .ap-hero-meta {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin: 0;
  }

  /* Buttons stacked on the FAR RIGHT */
  .ap-hero-actions {
    flex: 0 0 auto !important;
    width: clamp(220px, 22vw, 280px) !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: stretch !important;
    gap: 10px !important;
    position: relative;
    z-index: 2;
  }
  .ap-hero-actions .ap-share-help { display: block; width: 100%; }
  .ap-hero-actions .ap-btn {
    width: 100% !important;
    justify-content: center !important;
    text-align: center;
    white-space: nowrap;
  }

  /* Fundraiser zone is the last item in the button stack */
  .ap-hero-actions .ap-fr-zone { width: 100%; margin: 0; }
  /* NOTE: do NOT force `display` here — the fundraiser JS toggles the empty/
     active states via inline display + the .ap-fr-zone--active parent class. */
  .ap-hero-actions .ap-fr-zone-empty {
    padding: 0 !important;
    margin: 0 !important;
    min-height: 0 !important;
    background: none !important;
    border: none !important;
  }
  .ap-btn--fr-start {
    width: 100% !important;
    justify-content: center !important;
    background: linear-gradient(135deg, #22c55e 0%, #16a34a 100%) !important;
    color: #fff !important;
    border: 1px solid rgba(255,255,255,0.14) !important;
    border-radius: 999px !important;
    padding: 12px 18px !important;
    font-size: 13.5px !important;
    font-weight: 800 !important;
    cursor: pointer;
    box-shadow: 0 14px 34px rgba(22,163,74,0.30) !important;
    transition: transform 0.15s ease, opacity 0.15s;
  }
  .ap-btn--fr-start:hover { transform: translateY(-1px); opacity: 0.94; }

  /* Active fundraiser — compact card that replaces the green button */
  /* Active card: restyle only — `display` stays controlled by the JS inline
     toggle (flex when shown, none when hidden) so it never shows without data. */
  .ap-hero-actions .ap-fr-zone-active {
    flex-direction: column !important;
    gap: 10px !important;
    width: 100%;
    padding: 14px 16px !important;
    background: linear-gradient(135deg, #14532d 0%, #166534 60%, #15803d 100%) !important;
    border: 1px solid rgba(255,255,255,0.12) !important;
    border-radius: 16px !important;
    box-shadow: 0 14px 34px rgba(20,83,45,0.28) !important;
  }
  .ap-hero-actions .ap-fr-zone-active-top { display: block; }
  .ap-hero-actions .ap-fr-zone-badge {
    display: inline-flex; align-items: center; gap: 6px;
    font-size: 9.5px; font-weight: 900; letter-spacing: 0.08em; text-transform: uppercase;
    color: #bbf7d0; margin-bottom: 6px;
  }
  .ap-hero-actions .ap-fr-zone-title {
    font-size: 14px !important; font-weight: 800; color: #fff !important; margin: 0 0 2px;
    white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
