  .ap-hero-actions .ap-fr-zone-progress { display: flex; flex-direction: column; gap: 6px; }
  .ap-hero-actions .ap-fr-zone-progress-meta {
    display: flex; justify-content: space-between; font-size: 11px; color: rgba(255,255,255,0.8);
  }
  .ap-hero-actions .ap-fr-zone-progress-meta strong { color: #fff; }
  .ap-hero-actions .ap-btn--fr-details {
    width: 100%; background: rgba(255,255,255,0.16); color: #fff;
    border: 1px solid rgba(255,255,255,0.22); border-radius: 10px;
