    transition: background 0.15s;
  }
  .ap-hero-actions .ap-btn--fr-details:hover { background: rgba(255,255,255,0.26); }

  /* Hero responsive — stack on tablet/phone */
  @media (max-width: 980px) {
    .ap-hero {
      flex-direction: column !important;
      align-items: stretch !important;
      text-align: left;
    }
    .ap-hero-logo {
      width: clamp(110px, 30vw, 160px) !important;
      height: clamp(110px, 30vw, 160px) !important;
