    }
    .ap-hero-actions { width: 100% !important; }
  }
  @media (max-width: 560px) {
    .ap-hero-actions { display: grid !important; grid-template-columns: 1fr 1fr; gap: 8px; }
    .ap-hero-actions .ap-fr-zone { grid-column: 1 / -1; }
