/* ═══════════════════════════════════════════════════════════════
   REDESIGN v3 — Products tab as a card grid (matches Add Products)
   ═══════════════════════════════════════════════════════════════ */

  /* Wrapper is now a plain block (was a 2-col grid for the old two sections)
     so the single product list spans the full width. */
  .ap-products-grid {
    display: block !important;
    grid-template-columns: none !important;
  }

  .ap-product-list {
    display: grid !important;
    grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)) !important;
    gap: 18px !important;
    padding: 4px 0 8px !important;
  }

  /* Each product becomes a vertical card */
  .ap-product-row {
    position: relative !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: stretch !important;
    gap: 0 !important;
    padding: 0 !important;
    background: #fff !important;
    border: 1.5px solid rgba(17,16,14,0.08) !important;
    border-radius: 20px !important;
    overflow: hidden !important;
    box-shadow: 0 2px 14px rgba(17,16,14,0.05) !important;
    transition: transform 0.2s cubic-bezier(.34,1.56,.64,1), box-shadow 0.18s ease, border-color 0.18s ease !important;
  }
  /* "Custom" badge overlaid on pro-built product cards */
  .ap-product-badge {
    position: absolute; top: 10px; left: 10px; z-index: 2;
    background: rgba(17,16,14,0.72);
    backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px);
    color: #fff; font-size: 9.5px; font-weight: 800;
    letter-spacing: 0.06em; text-transform: uppercase;
    padding: 4px 9px; border-radius: 999px;
  }
  /* Sits opposite the CUSTOM pill rather than under it: both are absolutely
     positioned to the same corner, so a second one in the same spot would
     simply cover the first. */
  .ap-product-badge--includes {
    left: auto; right: 10px;
    background: rgba(17,16,14,0.86);
    letter-spacing: 0.04em;
  }
  /* Products panel head: count + view-live-store link on the right */
  .ap-panel-head-right { display: flex; align-items: center; gap: 12px; flex-shrink: 0; }
  .ap-product-row:hover {
    transform: translateY(-4px) !important;
    box-shadow: 0 18px 44px rgba(17,16,14,0.12) !important;
    border-color: rgba(183,163,106,0.5) !important;
  }

  /* Image on top, full-width square */
  .ap-product-thumb,
  .ap-product-thumb-empty {
    width: 100% !important;
    aspect-ratio: 1 !important;
    height: auto !important;
    border-radius: 0 !important;
    background: #f5f1e8 !important;
    display: flex !important;
    align-items: center;
    justify-content: center;
    flex: 0 0 auto !important;
  }
  .ap-product-thumb { object-fit: cover !important; }
  .ap-product-thumb-empty { font-size: 38px !important; }

  /* Title sits in a padded info block */
  .ap-product-title {
    display: block;
    padding: 14px 14px 0 !important;
    font-size: 14px !important;
    font-weight: 900 !important;
    color: #11100e !important;
    letter-spacing: -0.02em;
    line-height: 1.25;
    white-space: normal !important;
    overflow: visible !important;
    text-overflow: clip !important;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
  }

  /* Actions live at the bottom of the card.
     Layout: [ Hide | Delete ] on row 1, prominent [ Edit ] on row 2. */
  .ap-product-row__actions {
    display: flex !important;
    flex-wrap: wrap !important;
    gap: 8px !important;
    width: 100% !important;
    margin-top: auto !important;
    padding: 12px 12px 13px !important;
    justify-content: flex-start !important;
  }
  /* Hide + Delete share the top row, 50/50 */
  .ap-product-row__actions > .ap-btn--outline-sm,
  .ap-product-row__actions > .ap-btn--danger-sm {
    flex: 1 1 calc(50% - 4px) !important;
    min-width: 0 !important;
    min-height: 38px !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    font-size: 12.5px !important;
    font-weight: 700 !important;
    border-radius: 11px !important;
    white-space: nowrap;
  }
  /* Editor button gets its own full-width row — covers both the wrapped
     (placement/colors) case and the un-wrapped Pro Builder re-edit button. */
  .ap-product-row__actions > .ap-product-editor-wrap,
  .ap-product-row__actions > .ap-edit-placement-btn {
    flex: 1 1 100% !important;
    display: flex !important;
  }
  .ap-product-row__actions .ap-edit-placement-btn {
    width: 100% !important;
    min-height: 40px !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    gap: 6px;
    font-size: 13px !important;
    font-weight: 800 !important;
    border-radius: 11px !important;
    white-space: nowrap;
  }

  /* Hidden products dimmed */
  .ap-product-row[data-hidden="true"] { opacity: 0.55; }
  .ap-product-row[data-hidden="true"] .ap-product-title::after {
    content: " — Hidden";
    font-size: 11px; font-weight: 600; font-style: italic;
    color: rgba(17,16,14,0.42);
  }

  @media (max-width: 560px) {
    .ap-product-list { grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)) !important; gap: 12px !important; }
    .ap-product-title { font-size: 13px !important; }
  }

/* ═══════════════════════════════════════════════════════════════
   REDESIGN v3 — Tab label "Add Products" shortens to "Add" on phones.
   Higher specificity + !important so it beats the .ap-tab-label 8px rule
   (otherwise the full label stays and ::after stacks a 2nd "Add" word).
   ═══════════════════════════════════════════════════════════════ */
  @media (max-width: 480px) {
    .ap-main-tab-btn[data-main-tab="apPanelAddProducts"] .ap-tab-label {
      font-size: 0 !important;
      line-height: 0 !important;
    }
    .ap-main-tab-btn[data-main-tab="apPanelAddProducts"] .ap-tab-label::after {
      content: 'Add' !important;
      font-size: 8px !important;
      line-height: 1.15 !important;
      font-weight: 700;
    }
  }

/* ═══════════════════════════════════════════════════════════════
   EDITOR MODAL SLIM CHROME (v2) — the header bar ("Edit Logo
   Placement" + store title) wasted vertical space, especially on
   mobile. The header collapses to a floating ✕ and the editor
   iframe gets the full height. DELETE THIS BLOCK to restore the
   classic header bar.
   ═══════════════════════════════════════════════════════════════ */
  .ap-editor-header {
    position: absolute !important;
    top: 0 !important;
    right: 0 !important;
    z-index: 6;
    background: transparent !important;
    border: none !important;
    padding: 8px !important;
    pointer-events: none;
  }
  #apEditorTitle { display: none !important; }  /* kept in DOM for aria-labelledby */
  /* The host owns one exit throughout loading and editing. Embedded pro
     editors receive pb_open_id and suppress their duplicate exit control. */
  .ap-editor-close {
    display: flex !important;
    pointer-events: auto;
    width: 44px !important;
    height: 44px !important;
    border-radius: 50% !important;
    background: #fff !important;
    color: #142238 !important;
    -webkit-text-fill-color: #142238 !important;
    border: 1px solid #cbd0d7 !important;
    box-shadow: 0 2px 8px rgba(0,0,0,.14);
    backdrop-filter: blur(6px);
    -webkit-backdrop-filter: blur(6px);
    font-size: 20px !important;
  }
  .ap-editor-close:hover { background: #eddec2 !important; }
  .ap-editor-close:focus-visible { outline:3px solid #947337; outline-offset:3px; }
  .ap-editor-loading-screen { display:none;position:absolute;inset:0;z-index:5;align-items:center;justify-content:center;padding:24px;background:#faf9f5;text-align:center;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; }
  .ap-editor-loading .ap-editor-loading-screen { display:flex; }
  /* Keep the frame rendering under the opaque cover: visibility:hidden
     pauses requestAnimationFrame in embedded browsers and stalls artwork. */
  .ap-editor-loading .ap-editor-iframe { pointer-events:none; }
  .ap-editor-loading-copy { width:min(360px,100%); }
  .ap-editor-loading-copy strong { display:block;color:#142238;font-size:18px;font-weight:700;line-height:1.3;letter-spacing:0;margin:0; }
  .ap-editor-loading-copy span { display:block;margin-top:8px;font-size:13px;font-weight:400;line-height:1.5;color:#5b6470; }
  .ap-editor-spinner { width:30px;height:30px;box-sizing:border-box;margin:0 auto 16px;border:3px solid #e2dfd5;border-top-color:#142238;border-radius:50%;animation:apEditorSpin .8s linear infinite; }
  .ap-editor-loading-copy button { margin-top:16px;padding:10px 18px;background:#142238;color:#fff;border:0;border-radius:10px;font-family:inherit;font-size:14px;font-weight:700;cursor:pointer; }
  .ap-editor-loading-copy button[hidden] { display:none; }
  @keyframes apEditorSpin { to { transform:rotate(360deg); } }
  /* The dialog's height used to come from the iframe's min-height:640px.
     Give the dialog an explicit height so the iframe can simply fill it. */
  .ap-editor-dialog {
    position: relative;
    height: calc(100vh - 48px);
  }
  .ap-editor-iframe { min-height: 0 !important; flex: 1 1 auto !important; }
  @media (max-width: 900px) {
    .ap-editor-dialog { height: 100vh; height: 100dvh; }
  }

/* ═══════════════════════════════════════════════════════════════
   LIGHT HERO — the admin header was the one dark slab on an
   otherwise cream-and-gold page, and its text sat at 60-70% white
   on near-black. That combination is where "some wording is hard
   to see" came from. The palette above is already the site's; this
   brings the hero into it.

   The type and the logo tile come down with it. The heading was
   clamped to a 38px floor and the logo to 110px, so on a phone the
   store name and a picture of the logo filled the screen before
   any control appeared.

   Several rules this overrides are themselves !important, so these
   are too. DELETE THIS BLOCK to restore the dark hero.
   ═══════════════════════════════════════════════════════════════ */
  .ap-hero {
    background:
      radial-gradient(circle at 8% 0%, rgba(183,163,106,0.16), transparent 42%),
      linear-gradient(150deg, #fffdf9 0%, #fbf8f1 62%, #f7f2e7 100%) !important;
    border: 1px solid rgba(183,163,106,0.30) !important;
    box-shadow: 0 26px 80px rgba(17,16,14,0.09) !important;
  }

  /* This overlay existed to lift a dark gradient. On cream it only
     muddies it. */
  .ap-hero::before { background: none !important; }

  .ap-hero .ap-hero-info h1,
  .ap-hero h1 {
    color: var(--ap-text) !important;
    font-size: clamp(30px, 3.6vw, 52px) !important;
    line-height: 1.02 !important;
    letter-spacing: -0.045em !important;
  }

  .ap-hero .ap-hero-badge {
    background: rgba(183,163,106,0.16) !important;
    border: 1px solid rgba(183,163,106,0.42) !important;
    color: #6f5d28 !important;
  }

  .ap-hero .ap-hero-logo {
    background: #fff !important;
    border: 1px solid rgba(183,163,106,0.34) !important;
    box-shadow: 0 14px 40px rgba(17,16,14,0.10) !important;
  }

  .ap-hero .ap-hero-pill {
    color: rgba(17,16,14,0.68) !important;
    background: rgba(255,255,255,0.86) !important;
    border: 1px solid rgba(17,16,14,0.10) !important;
  }

  .ap-hero .ap-hero-pill--status {
    color: #0f6b45 !important;
    background: rgba(16,185,129,0.13) !important;
    border-color: rgba(16,185,129,0.34) !important;
  }

  /* Glass was white-on-transparent, which is invisible on cream.
     On a light hero these are the secondary actions, so they read
     as outlines and Share becomes the one solid button. */
  .ap-hero .ap-btn--glass {
    background: rgba(255,255,255,0.92) !important;
    border: 1px solid rgba(17,16,14,0.14) !important;
    color: var(--ap-text) !important;
    backdrop-filter: none !important;
  }
  .ap-hero .ap-btn--glass:hover {
    background: #fff !important;
    border-color: rgba(17,16,14,0.26) !important;
    color: var(--ap-text) !important;
  }

  .ap-hero .ap-btn--share-primary {
    background: var(--ap-accent) !important;
    color: #fff !important;
    border: 1px solid var(--ap-accent) !important;
    box-shadow: 0 12px 30px rgba(17,16,14,0.18) !important;
  }
  .ap-hero .ap-btn--share-primary:hover {
    background: #2a2721 !important;
    color: #fff !important;
  }

  /* Sits on the cream hero, not on the green fundraiser card, so it
     needs the same treatment as the other hero buttons. */
  .ap-hero-actions .ap-fr-zone-empty .ap-btn--fr-details,
  .ap-hero .ap-fr-zone-empty .ap-btn--fr-details {
    background: rgba(255,255,255,0.92) !important;
    border: 1px solid rgba(17,16,14,0.14) !important;
    color: var(--ap-text) !important;
  }

  @media (max-width: 700px) {
    .ap-hero {
      padding: 18px 16px !important;
      border-radius: 24px !important;
      gap: 14px !important;
      margin-bottom: 12px !important;
    }

    /* 38px was still a headline shouting on a 390px screen. */
    .ap-hero .ap-hero-info h1,
    .ap-hero h1 {
      font-size: clamp(23px, 6.4vw, 31px) !important;
      line-height: 1.06 !important;
      letter-spacing: -0.03em !important;
    }

    /* 110px of logo above the fold, on top of the name, left no
       room for the thing the page is for. */
    .ap-hero .ap-hero-logo {
      width: 62px !important;
      height: 62px !important;
      border-radius: 18px !important;
    }
    .ap-hero .ap-hero-logo span { font-size: 25px !important; }
    .ap-hero .ap-hero-logo img { border-radius: 18px !important; }

    .ap-hero .ap-hero-info { gap: 9px !important; }

    .ap-hero .ap-hero-badge {
      font-size: 9.5px !important;
      letter-spacing: 0.09em !important;
      padding: 5px 10px !important;
    }

    /* 10px uppercase at 66% opacity is the exact combination that
       stops being readable on a phone in daylight. */
    .ap-hero .ap-hero-pill {
      min-height: 28px !important;
      font-size: 10.5px !important;
      letter-spacing: 0.04em !important;
      color: rgba(17,16,14,0.74) !important;
    }

    .ap-hero .ap-btn { min-height: 46px !important; font-size: 14px !important; }
  }

  /* The name and the logo side by side is the one arrangement that
     survives a narrow screen: the tile stays small, the name gets
     the remaining width, and the controls start above the fold. */
  @media (max-width: 560px) {
    .ap-hero {
      display: grid !important;
      grid-template-columns: auto minmax(0, 1fr) !important;
      align-items: center !important;
      column-gap: 12px !important;
      row-gap: 14px !important;
    }
    .ap-hero .ap-hero-logo { grid-column: 1; grid-row: 1; }
    .ap-hero .ap-hero-info { grid-column: 2; grid-row: 1; }
    .ap-hero .ap-hero-actions { grid-column: 1 / -1; grid-row: 2; }
  }

  /* The action buttons are a two-up grid on a phone, but they were
     also `white-space: nowrap` with 1fr columns, so "← Dashboard"
     set a minimum wider than its share and pushed the whole hero
     past the edge of the screen. Columns that are allowed to
     shrink, and labels that are allowed to wrap, keep it inside. */
  @media (max-width: 560px) {
    .ap-hero .ap-hero-actions {
      grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) !important;
    }
    .ap-hero .ap-hero-actions .ap-btn {
      white-space: normal !important;
      min-width: 0 !important;
      padding-left: 10px !important;
      padding-right: 10px !important;
    }
    /* Share is the primary action and the fundraiser is a block of
       its own; both get the full width. */
    .ap-hero .ap-hero-actions .ap-share-help,
    .ap-hero .ap-hero-actions .ap-fr-zone {
      grid-column: 1 / -1 !important;
    }
  }

/* ═══════════════════════════════════════════════════════════════
   READABLE TAB LABELS — the bar under the hero set its labels at
   8px and 54% opacity on a phone. That is smaller than anything
   else on the page and lighter than the body text, which is the
   combination that makes a control look disabled rather than
   simply unselected. 10.5px at 72% is still quiet next to the
   selected tab and is actually legible.
   ═══════════════════════════════════════════════════════════════ */
  @media (max-width: 700px) {
    .ap-main-tabs .ap-tab-label {
