  /* The shortened "Add" has to move with them, or it is the one
     label still set at 8px. */
  @media (max-width: 480px) {
    .ap-main-tab-btn[data-main-tab="apPanelAddProducts"] .ap-tab-label::after {
      font-size: 10.5px !important;
      line-height: 1.2 !important;
    }
