/* ═══════════════════════════════════════════════════════════════
   READABLE INK — the muted ramp finally clears WCAG AA.
   The dark "Command Center" overlay has been removed, so this cream
   theme is what actually renders again. Its quiet text was tuned by
   eye and sat at 0.46–0.55 ink alpha, i.e. 3.1–4.2:1 on white —
   below the 4.5:1 that small text needs. The two slate greys
   (#94a3b8, #64748b) were worse still. This wave lifts the whole
   ramp to 0.62–0.68 and retires the greys; it is deliberately the
   last thing in the file so it wins the cascade without anyone
   having to find and edit the earlier waves.
   Verified by tests/js_harness/admin_powers_integrity.js, which
   computes these ratios from the shipped CSS.
   ═══════════════════════════════════════════════════════════════ */
  :root {
    --ap-muted: rgba(17,16,14,0.64);        /* helpers, sub-copy, inactive tabs */
    --ap-muted-strong: rgba(17,16,14,0.68); /* tiny uppercase labels need more */
    --ap-border-strong: rgba(17,16,14,0.16);
  }

  /* Tiny uppercase labels — the smallest type on the page. */
  .ap-panel-kicker,
  .ap-label,
  .ap-frw-legal-intro,
  .ap-frd-row-label,
  .ap-frd-stat-cell-lbl {
    color: var(--ap-muted-strong) !important;
  }

  /* Helper and secondary copy. */
  .ap-helper,
  .ap-frw-helper,
  .ap-product-box-sub,
  .ap-custom-builders-sub,
  .ap-frw-stripe-test-note,
  .ap-frw-label,
  .ap-frw-toggle-copy p,
  .ap-frw-stripe-card p,
  .ap-rebuild-sub,
  #apSettingsLogoStatus {
    color: var(--ap-muted) !important;
  }

  /* Unselected tabs sit on cream, which is a touch darker than white. */
  .ap-main-tab-btn { color: var(--ap-muted) !important; }
  .ap-main-tab-btn.active { color: var(--ap-text) !important; }

  /* Placeholders had no rule at all, so the UA default rendered. */
  .ap-input::placeholder,
  .ap-textarea::placeholder,
  .ap-frw-input::placeholder,
  .ap-nuke-input::placeholder,
  input::placeholder,
  textarea::placeholder {
    color: rgba(17,16,14,0.55);
    opacity: 1;
  }

  /* The ✕ on the Share modal used var(--ap-text) on a hardcoded white,
     which the dark overlay had turned white-on-white. Pin the ink. */
  .ap-share-close { color: #11100e !important; background: #fff !important; }

  /* Disabled controls: a muted surface, not half-opacity, so the label
     stays readable and the state is still obviously "off". */
  .ap-btn:disabled,
  .ap-btn[disabled] {
    opacity: 1 !important;
    background: rgba(17,16,14,0.06) !important;
    border-color: rgba(17,16,14,0.12) !important;
    color: rgba(17,16,14,0.45) !important;
    box-shadow: none !important;
    cursor: not-allowed;
  }
  /* This rule lost to .ap-edit-placement-btn on source order before; being
     last, it now actually renders. */
  .ap-edit-placement-btn--disabled,
  .ap-edit-placement-btn--disabled:hover {
    background: rgba(17,16,14,0.08) !important;
    border-color: rgba(17,16,14,0.14) !important;
    color: rgba(17,16,14,0.45) !important;
    box-shadow: none !important;
    cursor: not-allowed;
  }

  /* Green fundraiser CTAs: white text needs a darker green than #22c55e. */
  .ap-btn--fr-start,
  .ap-btn--fr-edit-wizard,
  #apFrLaunchBtn {
    background: linear-gradient(135deg, #15803d 0%, #166534 100%) !important;
  }
  .ap-btn--fr-start:hover,
  .ap-btn--fr-edit-wizard:hover,
  #apFrLaunchBtn:hover {
    background: linear-gradient(135deg, #166534 0%, #14532d 100%) !important;
  }
  /* "Edit / End →" on the pale green settings row. */
  .ap-fr-active-edit { color: #14532d !important; }

/* ═══════════════════════════════════════════════════════════════
   TIDY — small things the light theme never finished.
   ═══════════════════════════════════════════════════════════════ */

  /* Product status pill (Live / Hidden). The old --visible/--hidden rules
     used slate greys from the first draft; bring them into the cream/gold
     palette and let the pill replace the "— Hidden" suffix on the title. */
  .ap-badge--status {
    font-size: 10px; font-weight: 850; letter-spacing: 0.08em; text-transform: uppercase;
    padding: 4px 9px; border-radius: 999px; border: 1px solid transparent; line-height: 1.2;
  }
  .ap-badge--visible { background: rgba(16,185,129,0.12) !important; color: #065f46 !important; border-color: rgba(16,185,129,0.28) !important; }
  .ap-badge--hidden  { background: rgba(17,16,14,0.06) !important;  color: rgba(17,16,14,0.62) !important; border-color: rgba(17,16,14,0.14) !important; }
  .ap-product-row[data-hidden="true"] .ap-product-title::after { content: none !important; }

  /* Five fundraiser-wizard classes had no CSS in any file and rendered as
     bare text. Same card vocabulary as the rest of the wizard. */
  .ap-frw-stripe-intro {
    padding: 16px 18px; border-radius: 16px;
    background: rgba(255,255,255,0.72); border: 1px solid var(--ap-border);
    margin-bottom: 14px;
  }
  .ap-frw-stripe-intro-header { display: flex; align-items: center; gap: 12px; margin-bottom: 10px; }
  .ap-frw-stripe-intro-icon {
