/* Stella & Sage support-page experience
 * Repairs customer-facing support links, adds phone/text permission fields,
 * and provides a real contact form that emails the support inbox.
 */
(() => {
  'use strict';

  const ENDPOINT = 'https://printfulautomation-production.up.railway.app/support/cases';

  const ready = (callback) => {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', callback, { once: true });
    } else {
      callback();
    }
  };

  const escapeHtml = (value) => String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#039;');

  const readError = async (response, fallback) => {
    try {
      const data = await response.json();
      return data.detail || data.message || fallback;
    } catch (_) {
      return fallback;
    }
  };

  ready(() => {
    const root = document.querySelector('.ss-help');
    if (!root || root.dataset.ssExperienceReady === '1') return;
    root.dataset.ssExperienceReady = '1';

    const context = window.SS_SUPPORT_CONTEXT || {};
    const supportEmail = context.supportEmail || 'ryan.irwin@stellaandsagecompany.com';
    const actions = Array.from(root.querySelectorAll('.ss-help__action'));

    const setAction = (action, { href, title, description, icon }) => {
      if (!action) return;
      if (href) action.setAttribute('href', href);
      const strong = action.querySelector('strong');
      const small = action.querySelector('small');
      const iconNode = action.querySelector('.ss-help__icon');
      if (strong) strong.textContent = title;
      if (small) small.textContent = description;
      if (iconNode) iconNode.textContent = icon;
    };

    setAction(actions[0], {
      href: '/account',
      title: 'My orders',
      description: 'Open an order to view fulfillment and tracking updates.',
      icon: '↗'
    });

    setAction(actions[2], {
      href: '/policies/refund-policy',
      title: 'Refund policy',
      description: 'See which production and delivery problems qualify for help.',
      icon: '✓'
    });

    setAction(actions[3], {
      href: '#contact-support',
      title: 'Contact support',
      description: 'Send Ryan a message directly from this page.',
      icon: '✉'
    });

    root.querySelectorAll('a[href="/pages/online-tracking"]').forEach((link) => {
      link.setAttribute('href', '/account');
      if (link.textContent.trim().toLowerCase().includes('track')) {
        link.textContent = 'View my orders';
      }
    });

    const style = document.createElement('style');
    style.textContent = `
      .ss-help .ss-support-checkbox{display:flex!important;flex-direction:row!important;align-items:flex-start;gap:10px!important;padding:12px 14px;border:1px solid rgba(17,16,14,.11);border-radius:12px;background:#fff;font-size:12px!important;font-weight:650!important;line-height:1.45}
      .ss-help .ss-support-checkbox input{width:17px!important;height:17px!important;flex:0 0 auto;margin:1px 0 0;padding:0!important}
      .ss-help .ss-contact-panel{background:#f7f4ed;border:1px solid rgba(17,16,14,.08);border-radius:24px;padding:28px;margin:18px 0 38px}
      .ss-help .ss-contact-panel[hidden]{display:none}
      .ss-help .ss-contact-panel__head{display:flex;justify-content:space-between;gap:24px;align-items:flex-start;margin-bottom:24px}
      .ss-help .ss-contact-panel__head>div{max-width:720px}
      .ss-help .ss-contact-panel__head p:last-child{font-size:16px;line-height:1.65;color:#68645c}
      .ss-help .ss-contact-panel__close{border:0;background:#fff;width:40px;height:40px;border-radius:50%;font-size:25px;cursor:pointer}
      .ss-help .ss-contact-panel__grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}
      .ss-help .ss-contact-panel__full{grid-column:1/-1}
      .ss-help .ss-contact-panel__submit{display:flex;align-items:center;gap:18px;margin-top:18px}
      .ss-help .ss-contact-panel__submit button{border:0;border-radius:999px;background:#11100e;color:#fff;padding:14px 22px;font-weight:900;cursor:pointer;white-space:nowrap}
      .ss-help .ss-contact-panel__submit button[disabled]{opacity:.55;cursor:wait}
      .ss-help .ss-contact-panel__note{font-size:12px;line-height:1.45;color:#68645c;margin:0}
      @media(max-width:600px){
        .ss-help .ss-contact-panel{padding:20px 16px}
        .ss-help .ss-contact-panel__grid{grid-template-columns:1fr}
        .ss-help .ss-contact-panel__full{grid-column:auto}
        .ss-help .ss-contact-panel__submit{align-items:stretch;flex-direction:column}
      }
    `;
    document.head.appendChild(style);

    const casePanel = root.querySelector('[data-ss-case-panel]');
    const caseForm = root.querySelector('[data-ss-case-form]');
    const caseStatus = root.querySelector('[data-ss-case-status]');

    if (caseForm) {
      const grid = caseForm.querySelector('.ss-help__form-grid');
      const emailInput = caseForm.querySelector('input[name="email"]');
      if (emailInput && !emailInput.value && context.email) emailInput.value = context.email;

      if (grid && !caseForm.querySelector('input[name="phone"]')) {
        const phoneLabel = document.createElement('label');
        phoneLabel.innerHTML = `
          <span>Cell phone <small>(optional)</small></span>
          <input name="phone" type="tel" autocomplete="tel" placeholder="Best number to reach you">
        `;

        const consentLabel = document.createElement('label');
        consentLabel.className = 'ss-support-checkbox';
        consentLabel.innerHTML = `
          <input name="text_permission" type="checkbox" value="yes">
          <span>It is okay for Stella & Sage to text me about this support request. Message and data rates may apply.</span>
        `;

        const emailLabel = emailInput?.closest('label');
        if (emailLabel) {
          emailLabel.insertAdjacentElement('afterend', consentLabel);
          emailLabel.insertAdjacentElement('afterend', phoneLabel);
        } else {
          grid.append(phoneLabel, consentLabel);
        }

        const phoneInput = phoneLabel.querySelector('input');
        if (phoneInput && context.phone) phoneInput.value = context.phone;
      }

      caseForm.addEventListener('submit', async (event) => {
        event.preventDefault();
        event.stopImmediatePropagation();

        if (!caseForm.reportValidity()) return;
        caseStatus.textContent = '';
        caseStatus.className = 'ss-help__status';

        const submit = caseForm.querySelector('button[type="submit"]');
        submit.disabled = true;
        submit.textContent = 'Submitting…';

        try {
          const data = new FormData(caseForm);
          const phone = String(data.get('phone') || '').trim();
          const textPermission = data.get('text_permission') === 'yes' ? 'Yes' : 'No';
          const originalDescription = String(data.get('description') || '').trim();
          data.set(
            'description',
            `Cell phone: ${phone || '(not provided)'}\nText permission: ${textPermission}\n\n${originalDescription}`
          );

          const response = await fetch(ENDPOINT, {
            method: 'POST',
            body: data,
            headers: { Accept: 'application/json' }
          });

          if (!response.ok) {
            throw new Error(await readError(response, 'We could not submit the request.'));
          }

          const result = await response.json();
          caseStatus.textContent = `${result.message || 'Your request was submitted.'} Case number: ${result.case_id}.`;
          caseStatus.classList.add('is-success');
          caseForm.reset();
          if (emailInput && context.email) emailInput.value = context.email;
          const phoneInput = caseForm.querySelector('input[name="phone"]');
          if (phoneInput && context.phone) phoneInput.value = context.phone;
        } catch (error) {
          caseStatus.textContent = `${error.message || 'We could not submit the request.'} You can also email ${supportEmail}.`;
          caseStatus.classList.add('is-error');
        } finally {
          submit.disabled = false;
          submit.textContent = 'Submit support request';
        }
      }, true);
    }

    const contactPanel = document.createElement('div');
    contactPanel.className = 'ss-contact-panel';
    contactPanel.id = 'contact-support';
    contactPanel.hidden = true;
    contactPanel.innerHTML = `
      <div class="ss-contact-panel__head">
        <div>
          <p class="ss-help__eyebrow">CONTACT SUPPORT</p>
          <h2>Send us a message</h2>
          <p>Your message is emailed directly to Ryan. Include an order number in the message when your question is about an order.</p>
        </div>
        <button type="button" class="ss-contact-panel__close" aria-label="Close contact form">×</button>
      </div>
      <form data-ss-contact-form novalidate>
        <div class="ss-contact-panel__grid">
          <label>
            <span>Your name</span>
            <input name="contact_name" type="text" autocomplete="name" value="${escapeHtml(context.name || '')}" required>
          </label>
          <label>
            <span>Your email</span>
            <input name="contact_email" type="email" autocomplete="email" value="${escapeHtml(context.email || '')}" required>
          </label>
          <label>
            <span>Cell phone <small>(optional)</small></span>
            <input name="contact_phone" type="tel" autocomplete="tel" value="${escapeHtml(context.phone || '')}" placeholder="Best number to reach you">
          </label>
          <label>
            <span>What can we help with?</span>
            <select name="contact_subject" required>
              <option value="">Choose one</option>
              <option value="Order question">Order question</option>
              <option value="Store or admin help">Store or admin help</option>
              <option value="Tax-exempt organization">Tax-exempt organization</option>
              <option value="Product question">Product question</option>
              <option value="Something else">Something else</option>
            </select>
          </label>
          <label class="ss-contact-panel__full">
            <span>Message</span>
            <textarea name="contact_message" rows="6" minlength="12" maxlength="4000" placeholder="Tell us what you need help with." required></textarea>
          </label>
          <label class="ss-support-checkbox ss-contact-panel__full">
            <input name="contact_text_permission" type="checkbox" value="yes">
            <span>It is okay for Stella & Sage to text me about this message. Message and data rates may apply.</span>
          </label>
        </div>
        <div class="ss-contact-panel__submit">
          <button type="submit">Send message</button>
          <p class="ss-contact-panel__note">Most messages receive a response within one business day.</p>
        </div>
        <div class="ss-help__status" data-ss-contact-status role="status" aria-live="polite"></div>
      </form>
    `;

    if (casePanel) casePanel.insertAdjacentElement('afterend', contactPanel);
    else root.querySelector('.ss-help__actions')?.insertAdjacentElement('afterend', contactPanel);

    const openContact = () => {
      if (casePanel) casePanel.hidden = true;
      root.querySelector('[data-ss-open-case]')?.setAttribute('aria-expanded', 'false');
      contactPanel.hidden = false;
      contactPanel.scrollIntoView({ behavior: 'smooth', block: 'start' });
      window.setTimeout(() => contactPanel.querySelector('input[name="contact_name"]')?.focus(), 350);
    };

    root.addEventListener('click', (event) => {
      if (!event.target.closest('a[href="#contact-support"]')) return;
      event.preventDefault();
      openContact();
    });

    contactPanel.querySelector('.ss-contact-panel__close')?.addEventListener('click', () => {
      contactPanel.hidden = true;
      actions[3]?.focus();
    });

    if (window.location.hash === '#contact-support') openContact();

    const contactForm = contactPanel.querySelector('[data-ss-contact-form]');
    const contactStatus = contactPanel.querySelector('[data-ss-contact-status]');

    contactForm?.addEventListener('submit', async (event) => {
      event.preventDefault();
      if (!contactForm.reportValidity()) return;

      contactStatus.textContent = '';
      contactStatus.className = 'ss-help__status';
      const submit = contactForm.querySelector('button[type="submit"]');
      submit.disabled = true;
      submit.textContent = 'Sending…';

      try {
        const form = new FormData(contactForm);
        const name = String(form.get('contact_name') || '').trim();
        const email = String(form.get('contact_email') || '').trim();
        const phone = String(form.get('contact_phone') || '').trim();
        const subject = String(form.get('contact_subject') || '').trim();
        const message = String(form.get('contact_message') || '').trim();
        const textPermission = form.get('contact_text_permission') === 'yes' ? 'Yes' : 'No';

        const data = new FormData();
        data.set('order_number', 'GENERAL');
        data.set('email', email);
        data.set('issue_type', 'other');
        data.set('item', subject);
        data.set('preferred_resolution', 'help');
        data.set('website', '');
        data.set(
          'description',
          `GENERAL SUPPORT MESSAGE\n\nName: ${name}\nCell phone: ${phone || '(not provided)'}\nText permission: ${textPermission}\nSubject: ${subject}\n\nMessage:\n${message}`
        );

        const response = await fetch(ENDPOINT, {
          method: 'POST',
          body: data,
          headers: { Accept: 'application/json' }
        });

        if (!response.ok) {
          throw new Error(await readError(response, 'We could not send your message.'));
        }

        const result = await response.json();
        contactStatus.textContent = `Your message was sent. Reference number: ${result.case_id}.`;
        contactStatus.classList.add('is-success');
        contactForm.reset();
        const nameInput = contactForm.querySelector('input[name="contact_name"]');
        const emailField = contactForm.querySelector('input[name="contact_email"]');
        const phoneField = contactForm.querySelector('input[name="contact_phone"]');
        if (nameInput && context.name) nameInput.value = context.name;
        if (emailField && context.email) emailField.value = context.email;
        if (phoneField && context.phone) phoneField.value = context.phone;
      } catch (error) {
        contactStatus.textContent = `${error.message || 'We could not send your message.'} You can also email ${supportEmail}.`;
        contactStatus.classList.add('is-error');
      } finally {
        submit.disabled = false;
        submit.textContent = 'Send message';
      }
    });
  });
})();

{% comment %}
  Stella & Sage Support Center
  - Order tracking and account links
  - Automated support intake with photo uploads
  - Return-policy guidance and FAQs
{% endcomment %}

{% assign tracking_url = section.settings.tracking_url | default: '/pages/online-tracking' %}
{% assign return_url = section.settings.return_url | default: routes.account_url %}
{% assign contact_email = section.settings.contact_email | default: shop.email %}
{% assign form_endpoint = section.settings.form_endpoint | default: 'https://printfulautomation-production.up.railway.app/support/cases' %}

<section class="ss-help" id="ss-help-{{ section.id }}">
  <div class="ss-help__wrap">
    <header class="ss-help__hero">
      <p class="ss-help__eyebrow">{{ section.settings.eyebrow | escape }}</p>
      <h1>{{ section.settings.heading | escape }}</h1>
      <p>{{ section.settings.subheading | escape }}</p>
    </header>

    <div class="ss-help__actions" aria-label="Support options">
      <a class="ss-help__action" href="{{ tracking_url }}">
        <span class="ss-help__icon" aria-hidden="true">↗</span>
        <span>
          <strong>Track my order</strong>
          <small>View fulfillment and shipping updates.</small>
        </span>
      </a>

      <button class="ss-help__action" type="button" data-ss-open-case aria-expanded="false" aria-controls="report-order-problem">
        <span class="ss-help__icon" aria-hidden="true">!</span>
        <span>
          <strong>Report an order problem</strong>
          <small>Damage, misprints, missing items, or delivery trouble.</small>
        </span>
      </button>

      <a class="ss-help__action" href="{{ return_url }}">
        <span class="ss-help__icon" aria-hidden="true">↶</span>
        <span>
          <strong>Request a return</strong>
          <small>Start from your account or order-status page.</small>
        </span>
      </a>

      <a class="ss-help__action" href="mailto:{{ contact_email | escape }}">
        <span class="ss-help__icon" aria-hidden="true">✉</span>
        <span>
          <strong>Contact support</strong>
          <small>Most messages receive a reply within one business day.</small>
        </span>
      </a>
    </div>

    <div class="ss-help__case" id="report-order-problem" data-ss-case-panel hidden>
      <div class="ss-help__case-head">
        <div>
          <p class="ss-help__eyebrow">ORDER HELP</p>
          <h2>Tell us what went wrong</h2>
          <p>Include clear photos for damaged, defective, incorrect, or misprinted items. This helps us resolve the problem faster.</p>
        </div>
        <button type="button" class="ss-help__close" data-ss-close-case aria-label="Close support form">×</button>
      </div>

      <form class="ss-help__form" data-ss-case-form enctype="multipart/form-data" novalidate>
        <div class="ss-help__form-grid">
          <label>
            <span>Order number</span>
            <input name="order_number" type="text" placeholder="#1234" autocomplete="off" required>
          </label>

          <label>
            <span>Email used for the order</span>
            <input name="email" type="email" autocomplete="email" required>
          </label>

          <label>
            <span>What happened?</span>
            <select name="issue_type" required>
              <option value="">Choose one</option>
              <option value="damaged">Arrived damaged</option>
              <option value="misprint">Print or production problem</option>
              <option value="wrong-item">Wrong item received</option>
              <option value="missing-item">Item missing from shipment</option>
              <option value="lost-shipment">Shipment appears lost or stalled</option>
              <option value="size-or-color">Size or color concern</option>
              <option value="personalization">Name or number problem</option>
              <option value="return">Return request</option>
              <option value="other">Something else</option>
            </select>
          </label>

          <label>
            <span>Affected item</span>
            <input name="item" type="text" placeholder="Example: youth royal-blue hoodie">
          </label>

          <label>
            <span>Preferred resolution</span>
            <select name="preferred_resolution">
              <option value="">No preference</option>
              <option value="replacement">Replacement</option>
              <option value="refund">Refund</option>
              <option value="exchange">Exchange</option>
              <option value="help">Help deciding</option>
            </select>
          </label>

          <label class="ss-help__photos">
            <span>Photos <small>(up to 4, 6 MB each)</small></span>
            <input name="photos" type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif" multiple>
          </label>
        </div>

        <label class="ss-help__full">
          <span>Describe the problem</span>
          <textarea name="description" rows="6" minlength="12" maxlength="4000" placeholder="Tell us what you expected, what arrived, and anything else that will help us review the order." required></textarea>
        </label>

        <label class="ss-help__honeypot" aria-hidden="true">
          Website
          <input name="website" type="text" tabindex="-1" autocomplete="off">
        </label>

        <div class="ss-help__submit-row">
          <button type="submit" class="ss-help__submit">Submit support request</button>
          <p class="ss-help__form-note">Submitting a request does not automatically approve a refund or replacement. We review the order and production details first.</p>
        </div>

        <div class="ss-help__status" data-ss-case-status role="status" aria-live="polite"></div>
      </form>
    </div>

    <section class="ss-help__overview" aria-label="Useful information">
      <div class="ss-help__delivery">
        <p class="ss-help__eyebrow">PLANNING AHEAD</p>
        <h2>From your order to your door.</h2>
        <div class="ss-help__timeline">
          <div><span>01 · FULFILLMENT</span><strong>3–5 business days</strong><p>Your items are made to order.</p></div>
          <div><span>02 · SHIPPING</span><strong>Up to one week</strong><p>Delivery time follows fulfillment.</p></div>
        </div>
        <p class="ss-help__estimate">These are estimates. Please order early for an event.</p>
        <a href="#shipping">Read shipping &amp; delivery details <span aria-hidden="true">→</span></a>
      </div>
      <aside class="ss-help__store">
        <p class="ss-help__eyebrow">STORE &amp; ACCOUNT HELP</p>
        <h2>Here for your group, too.</h2>
        <p>Need help joining a store, updating a design, or getting your group started?</p>
        <a href="/pages/private-storefronts">See how stores work <span aria-hidden="true">→</span></a>
        <a href="#contact-support">Ask us a question <span aria-hidden="true">→</span></a>
      </aside>
    </section>

    <div class="ss-help__faq" id="support-questions">
      <div class="ss-help__faq-head">
        <p class="ss-help__eyebrow">COMMON QUESTIONS</p>
        <h2>Find a quick answer.</h2><p>Shipping, returns, personalization, and managing your store.</p>
      </div>

      <div class="ss-help__faq-list">
        <details id="shipping" class="ss-help__shipping">
          <summary>Shipping &amp; delivery: when will my order arrive?</summary>
          <p>Every item is made to order. Please allow <strong>3–5 business days for fulfillment</strong>, followed by <strong>up to one week for shipping</strong>. Shipping time begins after your order has been fulfilled; it is additional to fulfillment time.</p>
          <p>Business days exclude weekends and holidays. Shipping within the United States is free. View your orders for fulfillment and tracking updates.</p>
          <p>These are estimates, not guaranteed arrival dates. Please order early for games, tournaments, and other events.</p>
          <p><a href="{{ tracking_url }}">View my orders</a></p>
        </details>
        <details>
          <summary>My tracking has not updated. What should I do?</summary>
          <p>Carrier scans can pause between facilities. Check the tracking link first. If the estimated delivery date has passed or the package appears stalled, submit an order-problem request above.</p>
        </details>
        <details>
          <summary>What happens if an item arrives damaged or misprinted?</summary>
          <p>Send the order number, the email used at checkout, a description, and clear photos of the item and packaging. We will compare the order with the production record and work toward a replacement or refund when approved.</p>
        </details>
        <details>
          <summary>Can I exchange a made-to-order item for another size?</summary>
          <p>Made-to-order sizing exchanges are not automatically covered. Submit a request and we will review what options are available. Size charts should be reviewed before checkout.</p>
        </details>
        <details>
          <summary>Can personalized names or numbers be changed after ordering?</summary>
          <p>Production can begin quickly, so changes are not guaranteed. Contact support immediately. Once production begins, buyer-entered names and numbers normally cannot be changed or returned unless the item is produced incorrectly.</p>
        </details>
        <details>
          <summary>How do tax-exempt organizations order?</summary>
          <p>Contact support before ordering and provide the required exemption documentation. Once approved, checkout must use the same email connected to the tax-exempt customer profile.</p>
        </details>
        <details>
          <summary>I organize a store. Where do I manage products and members?</summary>
          <p>Sign in and open your Dashboard. Store admins can enter Admin Powers to add products, update designs, and manage access without collecting money or placing a group order.</p>
        </details>
      </div>
    </div>
    <div class="ss-help__policy">
      <div>
        <p class="ss-help__eyebrow">MADE-TO-ORDER POLICY</p>
        <h2>Clear answers before you order</h2>
      </div>
      <div class="ss-help__policy-copy">
        <p><strong>Production problems:</strong> If an item arrives damaged, defective, misprinted, missing, or different from what was ordered, report it with clear photos. Approved cases may receive a replacement or refund.</p>
        <p><strong>Personalized items:</strong> Products made with a buyer-entered name or number are normally final sale unless they were produced incorrectly or arrived damaged.</p>
        <p><strong>Size, color, or change of mind:</strong> Because each item is made to order, these requests are not normally eligible for a free replacement. Contact us and we will review the options.</p>
        <p><strong>Event dates:</strong> Production and delivery estimates are not guaranteed arrival dates. Order early when purchasing for a tournament, trip, ceremony, or other fixed event.</p>
        <div class="ss-help__policy-links">
          <a href="/policies/refund-policy">Refund policy</a>
          <a href="/pages/support#shipping">Shipping policy</a>
          <a href="{{ tracking_url }}">Track an order</a>
        </div>
      </div>
    </div>

  </div>
</section>

<style>
  #ss-help-{{ section.id }} .ss-help__shipping{scroll-margin-top:110px}
  #ss-help-{{ section.id }} .ss-help__shipping:target{border-color:#b7a36a}

  #ss-help-{{ section.id }}{
    --ss-ink:#142238;
